fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If the grid is exactly 1×1, return its sole element; otherwise 0.0
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Precondition checks (will panic if violated)
    assert!(!x.is_empty(), "Input x must be non-empty");
    assert!(
        x.len() == y.len(),
        "Input arrays x and y must have the same length"
    );
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    for row in &c {
        assert!(!row.is_empty(), "Every row in the coefficient grid must be non-empty");
    }

    let n = x.len();
    let dv = default_value(&c);

    // If c is 1×1, dv == c[0][0], otherwise dv == 0.0.
    // Fill the output with dv for all positions.
    vec![dv; n]
}

fn main() {
    // Example usages:

    // 1×1 grid → all outputs equal the single coefficient
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0, 6.0];
    let c = vec![vec![7.0]];
    let out = lagval2d(x.clone(), y.clone(), c);
    assert_eq!(out, vec![7.0, 7.0, 7.0]);

    // Not 1×1 → all zeros
    let c2 = vec![vec![1.0, 2.0], vec![3.0, 4.0]];
    let out2 = lagval2d(x, y, c2);
    assert_eq!(out2, vec![0.0, 0.0, 0.0]);
}